package com.codepilot1c.core.edt.infobase;

import java.util.*;import java.util.List;import java.util.concurrent.*;import java.util.function.Consumer;import org.eclipse.swt.SWT;import org.eclipse.swt.widgets.*;import org.eclipse.ui.PlatformUI;import com.codepilot1c.core.edt.development.*;import com.codepilot1c.core.edt.runtime.EdtRuntimeService;import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;

/** Observes only a native question opened synchronously by this exact registered update thread. */

public final class NativeUpdateInteraction implements AutoCloseable {

 private static final Map<String,NativeUpdateInteraction> ENTRIES=new ConcurrentHashMap<>();private static final Map<Thread,NativeUpdateInteraction> THREADS=new ConcurrentHashMap<>();private static final String DIALOG="com._1c.g5.v8.dt.internal.platform.services.ui.infobases.sync.InfobaseSynchonizationQuestionDialog";

 private final String id="upd-"+UUID.randomUUID(),project,baseUuid,target,originScopeHash;private final Map<String,Object> originScope;private final boolean debugLaunch,updateAuthorized;private final Thread owner=Thread.currentThread();private final String job=BackgroundJobRegistry.currentJobId();private final Consumer<Map<String,Object>> progress=BackgroundJobRegistry.currentProgressSink();private final Display display;private final Listener filter;private volatile boolean active=true;private volatile String phase="native_update_running";private Shell pending;private String pendingHash;private long generation;private Map<String,Object> observation=Map.of();private volatile Map<String,Object> lastAnswer=Map.of();

 private NativeUpdateInteraction(String p,String uuid,String target,boolean debugLaunch,boolean authorized)throws Exception{this.project=p;this.baseUuid=uuid;this.target=target;this.debugLaunch=debugLaunch;this.updateAuthorized=authorized;originScope=Map.copyOf(new RegisteredInfobaseGateway().describeScope(p,uuid));originScopeHash=TaskSessionService.fingerprint(originScope);display=PlatformUI.getWorkbench().getDisplay();filter=e->{if(e.widget instanceof Shell shell&&display.getSyncThread()==owner)observe(shell);};if(THREADS.putIfAbsent(owner,this)!=null)throw new IllegalStateException("Nested native update scope");ENTRIES.entrySet().removeIf(e->!e.getValue().active);if(ENTRIES.size()>=32){THREADS.remove(owner,this);throw new IllegalStateException("Too many active native updates");}ENTRIES.put(id,this);try{display.syncExec(()->display.addFilter(SWT.Show,filter));}catch(Exception failure){ENTRIES.remove(id);THREADS.remove(owner,this);throw failure;}publish();}

 public static AutoCloseable observeUpdate(String p,com._1c.g5.v8.dt.platform.services.model.InfobaseReference base)throws Exception{if(org.osgi.framework.FrameworkUtil.getBundle(NativeUpdateInteraction.class)==null||!PlatformUI.isWorkbenchRunning())return ()->{};return begin(p,base);}

 public static NativeUpdateInteraction begin(String p,com._1c.g5.v8.dt.platform.services.model.InfobaseReference base)throws Exception{return new NativeUpdateInteraction(p,base.getUuid().toString(),InfobasePaths.hash(InfobasePaths.connectionIdentity(base.getConnectionString().asConnectionString())),false,false);}

 public static AutoCloseable observeLaunch(String project,boolean authorized)throws Exception{if(org.osgi.framework.FrameworkUtil.getBundle(NativeUpdateInteraction.class)==null||!PlatformUI.isWorkbenchRunning())return ()->{};return observeLaunch(project,new EdtRuntimeService().resolveDefaultInfobase(project),authorized);}
 public static AutoCloseable observeLaunch(String p,com._1c.g5.v8.dt.platform.services.model.InfobaseReference base,boolean authorized)throws Exception{if(org.osgi.framework.FrameworkUtil.getBundle(NativeUpdateInteraction.class)==null||!PlatformUI.isWorkbenchRunning())return ()->{};if(base==null)throw new IllegalStateException("Exact launch base required");var previous=THREADS.get(Thread.currentThread());if(previous!=null){if(previous.debugLaunch&&previous.project.equals(p)&&previous.baseUuid.equals(base.getUuid().toString()))return ()->{};throw new IllegalStateException("Another native scope owns this thread");}return new NativeUpdateInteraction(p,base.getUuid().toString(),InfobasePaths.hash(InfobasePaths.connectionIdentity(base.getConnectionString().asConnectionString())),true,authorized);}
 public static boolean applicationQuestion(String message,List<String> labels,String project){String text=message.toLowerCase(Locale.ROOT);var names=labels.stream().map(NativeUpdateInteraction::normalized).toList();return project!=null&&!project.isBlank()&&text.contains(project.toLowerCase(Locale.ROOT))&&(text.contains("не синхронизирована")||text.contains("not synchronized"))&&names.size()==3&&names.stream().filter(v->Set.of("обновить и запустить","update and launch","update and run").contains(v)).count()==1&&names.stream().filter(v->Set.of("запустить без обновления","launch without updating","run without updating","run without update").contains(v)).count()==1&&names.stream().filter(v->Set.of("отменить","отмена","cancel").contains(v)).count()==1;}
 static String normalized(String text){return text.replace("&","").trim().toLowerCase(Locale.ROOT);}

 public static boolean exclusiveQuestion(String message,java.util.List<String> labels){String text=message.toLowerCase(Locale.ROOT);boolean lock=text.contains("exclusive lock")||text.contains("исключительной блокировки")||text.contains("монопольного доступа");long retry=labels.stream().map(NativeUpdateInteraction::normalized).filter(s->s.equals("retry")||s.equals("повторить")).count();long cancel=labels.stream().map(NativeUpdateInteraction::normalized).filter(s->s.equals("cancel")||s.equals("отмена")).count();return lock&&retry==1&&cancel==1&&labels.size()>=2&&labels.size()<=3&&labels.stream().map(NativeUpdateInteraction::normalized).allMatch(v->Set.of("retry","повторить","cancel","отмена","update dynamically","обновить динамически").contains(v));}
 public static boolean dynamicAvailable(Map<String,Object> question){
  if(!"exclusive_access".equals(question.get("kind"))||!(question.get("choices") instanceof List<?> choices))return false;
  return choices.stream().filter(v->v instanceof Map<?,?>).map(v->(Map<?,?>)v).filter(v->Boolean.TRUE.equals(v.get("enabled"))&&Set.of("update dynamically","обновить динамически").contains(normalized(Objects.toString(v.get("label"))))).count()==1;
 }
 private static void requireDynamicAccess(){var config=com.codepilot1c.core.mcp.host.McpHostConfigStore.getInstance().load();var policy=new com.codepilot1c.core.mcp.host.DefaultMcpToolExposurePolicy(config);if(config.getMutationPolicy()!=com.codepilot1c.core.mcp.host.McpHostConfig.MutationPolicy.ALLOW||!policy.isExposed("edt_infobase_refresh")||!policy.isExposed("edt_update_control"))throw new IllegalStateException("Dynamic update operation not allowed");}
 public static List<Map<String,Object>> applyPersistentToPending(String project){var results=new ArrayList<Map<String,Object>>();for(var e:ENTRIES.values())if(e.project.equals(project)&&e.active&&e.pendingHash!=null&&dynamicAvailable(e.observation)){try{results.add(answer(e.id,e.pendingHash,"update_dynamic",true));}catch(Exception blocked){results.add(Map.of("update_id",e.id,"answered",false,"reason",blocked.getClass().getSimpleName()));}}return results;}
 private void tryPersistent(String expected){try{if(!DynamicUpdatePolicy.workspace().permission(project,baseUuid,target,originScopeHash).isEmpty())answer(id,expected,"update_dynamic",true);}catch(Exception blocked){/* Permission/revocation/binding drift leaves the original question waiting. */}}
 private static List<Control> controls(Composite parent){var list=new ArrayList<Control>();for(Control c:parent.getChildren()){list.add(c);if(c instanceof Composite composite)list.addAll(controls(composite));}return list;}

 private Map<String,Object> question(Shell shell){if(shell.isDisposed()||shell.getData()==null)return Map.of();String clazz=shell.getData().getClass().getName();var all=controls(shell);String message=all.stream().filter(c->c instanceof Label).map(c->((Label)c).getText()).reduce("",(a,c)->a+"\n"+c);var buttons=all.stream().filter(c->c instanceof Button).map(c->(Button)c).toList();var labels=buttons.stream().map(Button::getText).toList();String kind;
 if(DIALOG.equals(clazz)&&exclusiveQuestion(message,labels))kind="exclusive_access";else if(debugLaunch&&clazz.equals("org.eclipse.jface.dialogs.MessageDialog")&&Set.of("обновление приложения","application update","update application").contains(normalized(shell.getText()))&&applicationQuestion(message,labels,project))kind="application_update";else return Map.of();
 var choices=new ArrayList<Map<String,Object>>();for(Button button:buttons){if(!(button.getData() instanceof Integer index))return Map.of();choices.add(Map.of("index",index,"label",button.getText(),"enabled",button.isEnabled()));}return Map.of("kind",kind,"message_sha256",TaskSessionService.fingerprint(message),"choices",choices,"blocking_sessions",message.lines().filter(l->l.toLowerCase(Locale.ROOT).contains("компьютер:")||l.toLowerCase(Locale.ROOT).contains("computer:")).limit(8).map(l->l.substring(0,Math.min(512,l.length()))).toList());}

 private void observe(Shell shell){try{var q=question(shell);if(q.isEmpty()||!active)return;pending=shell;observation=q;generation++;pendingHash=TaskSessionService.fingerprint(List.of(id,generation,q));phase="application_update".equals(q.get("kind"))?"waiting_for_application_update":"waiting_for_exclusive_access";publish();if(updateAuthorized&&"application_update".equals(q.get("kind"))){String expected=pendingHash;display.asyncExec(()->{try{answer(id,expected,"update_and_launch");}catch(Exception failure){phase="waiting_for_application_update";publish();}});}else if(dynamicAvailable(q)){String expected=pendingHash;CompletableFuture.runAsync(()->tryPersistent(expected));}}catch(Exception ignored){/* An unrecognized dialog must never become actionable. */}}

 private void publish(){progress.accept(snapshot());}

 private Map<String,Object> snapshot(){var out=new LinkedHashMap<String,Object>();out.put("update_id",id);out.put("project",project);out.put("base_uuid",baseUuid);out.put("operation_scope",originScope);out.put("operation_scope_sha256",originScopeHash);if(job!=null)out.put("job_id",job);out.put("state",phase);out.put("stage",phase);out.put("terminal",!active);out.put("automatic_retry",false);out.put("new_update_dispatched",false);out.put("dynamic_update_allowed",dynamicAvailable(observation));out.put("last_answer",lastAnswer);out.put("dynamic_update_selected","update_dynamic".equals(lastAnswer.get("action")));out.put("runtime_clients_reloaded_verified",false);if(active&&pendingHash!=null){out.put("pending_question_sha256",pendingHash);out.put("blocking_sessions",observation.getOrDefault("blocking_sessions",List.of()));String kind=Objects.toString(observation.get("kind"));var actions=new ArrayList<String>(kind.equals("application_update")?List.of("update_and_launch","cancel"):List.of("retry","cancel","close_owned_and_retry"));if(dynamicAvailable(observation))actions.add("update_dynamic");out.put("allowed_actions",actions);out.put("question_kind",kind);var choices=new ArrayList<Map<String,Object>>();for(String action:actions)if(!action.equals("close_owned_and_retry"))choices.add(Map.of("id",action,"requires_database_update_authorization",(action.equals("update_and_launch")||action.equals("update_dynamic")),"command",Map.of("tool","edt.run","arguments",Map.of("op","edt_update_control","args",Map.of("action",action,"update_id",id,"expected_question_sha256",pendingHash)))));out.put("decision",Map.of("kind",kind,"decision_id",id,"decision_sha256",pendingHash,"choices",choices,"default_policy","ask_user_unless_current_task_or_scoped_permission_authorizes_action"));out.put("next_tool","edt_update_control");}return out;}

 private void currentBinding()throws Exception{var base=new EdtRuntimeService().resolveDefaultInfobase(project);if(base==null||!baseUuid.equals(base.getUuid().toString())||!target.equals(InfobasePaths.hash(InfobasePaths.connectionIdentity(base.getConnectionString().asConnectionString()))))throw new IllegalStateException("Update binding changed");if(!originScopeHash.equals(TaskSessionService.fingerprint(new RegisteredInfobaseGateway().describeScope(project,baseUuid))))throw new IllegalStateException("Update project path/context changed");}

 private void check(String expected){if(!active||pending==null||pending.isDisposed()||!Objects.equals(expected,pendingHash)||!TaskSessionService.fingerprint(observation).equals(TaskSessionService.fingerprint(question(pending))))throw new IllegalStateException("STALE_OR_UNOWNED_NATIVE_QUESTION");}

 private static NativeUpdateInteraction entry(String id){var e=ENTRIES.get(id);if(e==null)throw new IllegalStateException("Original update scope unavailable; never start another update to retry");return e;}

 public static Map<String,Object> list(String project){return Map.of("project",project,"updates",ENTRIES.values().stream().filter(e->e.project.equals(project)).map(NativeUpdateInteraction::snapshot).toList());}

 public static Map<String,Object> status(String id){var e=entry(id);if(!e.active)return e.snapshot();e.display.syncExec(()->{if(e.pending!=null&&e.pending.isDisposed()){e.pending=null;e.pendingHash=null;e.phase=e.active?"native_update_running":"native_update_returned";e.publish();}});return e.snapshot();}

 public static Map<String,Object> answer(String id,String expected,boolean cancel)throws Exception{return answer(id,expected,cancel?"cancel":"retry");}
 public static Map<String,Object> answer(String id,String expected,String action)throws Exception{return answer(id,expected,action,false);}
 private static Map<String,Object> answer(String id,String expected,String action,boolean persistent)throws Exception{if(action.equals("update_dynamic"))requireDynamicAccess();var e=entry(id);if(!"cancel".equals(action))e.currentBinding();final RuntimeException[] failure={null};e.display.syncExec(()->{try{e.check(expected);String kind=Objects.toString(e.observation.get("kind"));if(!(kind.equals("application_update")?Set.of("update_and_launch","cancel"):Set.of("retry","cancel","update_dynamic")).contains(action))throw new IllegalArgumentException("Answer does not apply to this question");Map<String,Object> permission=Map.of();if(action.equals("update_dynamic")){if(!dynamicAvailable(e.observation))throw new IllegalStateException("Native dynamic update button is unavailable");requireDynamicAccess();e.currentBinding();if(persistent){permission=DynamicUpdatePolicy.workspace().permission(e.project,e.baseUuid,e.target,e.originScopeHash);if(permission.isEmpty())throw new IllegalStateException("Dynamic update permission revoked");}}Set<String> labels=action.equals("cancel")?Set.of("cancel","отмена","отменить"):action.equals("retry")?Set.of("retry","повторить"):action.equals("update_dynamic")?Set.of("update dynamically","обновить динамически"):Set.of("update and launch","update and run","обновить и запустить");var buttons=controls(e.pending).stream().filter(c->c instanceof Button).map(c->(Button)c).filter(b->labels.contains(normalized(b.getText()))).toList();if(buttons.size()!=1||!buttons.get(0).isEnabled())throw new IllegalStateException("Native answer unavailable");e.lastAnswer=Map.of("action",action,"authorization_source",action.equals("update_dynamic")?(persistent?"scoped_persistent_permission":"explicit_once_command"):"explicit_command","policy_revision",Objects.toString(permission.get("revision"),""));e.pendingHash=null;e.phase=action.equals("cancel")?"cancel_requested":action.equals("retry")?"retry_requested":action.equals("update_dynamic")?"dynamic_update_requested":"update_and_launch_requested";e.publish();buttons.get(0).notifyListeners(SWT.Selection,new Event());e.pending=null;}catch(Exception err){failure[0]=err instanceof RuntimeException runtime?runtime:new IllegalStateException(err);}});if(failure[0]!=null)throw failure[0];return e.snapshot();}

 public static Map<String,Object> closeOwnedAndRetry(String id,String expected,String uiRun,String cleanupHash)throws Exception{var e=entry(id);e.currentBinding();final RuntimeException[] failure={null};e.display.syncExec(()->{try{e.check(expected);if(!"exclusive_access".equals(e.observation.get("kind")))throw new IllegalStateException("Owned client cleanup only applies to exclusive-access wait");}catch(RuntimeException err){failure[0]=err;}});if(failure[0]!=null)throw failure[0];var service=UiRunService.workspace();var run=service.details(uiRun);if(!e.project.equals(run.get("project"))||!e.baseUuid.equals(run.get("base_uuid"))||run.containsKey("reuse_from_ui_run_id"))throw new IllegalStateException("Owned UI client must belong to this exact update base");var cleaned=service.cleanup(uiRun,cleanupHash);if(!Boolean.TRUE.equals(cleaned.get("cleanup_verified")))throw new IllegalStateException("Owned UI cleanup incomplete; original update remains waiting");return answer(id,expected,false);}

 public void close(){active=false;phase="native_update_returned";THREADS.remove(owner,this);if(!display.isDisposed())display.syncExec(()->{display.removeFilter(SWT.Show,filter);pending=null;pendingHash=null;});publish();}

}
